export function Changelog({
  title = "{{title}}",
  entriesShown = {{entries_shown}},
  showNew = {{showNew}},
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  const entries = [
    { date: "14 Aug", text: "Faster search across every workspace, with instant results as you type." },
    { date: "02 Aug", text: "Dark mode now follows your system setting automatically." },
    { date: "27 Jul", text: "Export reports straight to CSV from any table view." },
  ];
  const listGap = variant === "compact" ? 8 : 14;
  return (
    <section style={{ fontFamily: "system-ui, sans-serif", fontSize: 16, lineHeight: 1.5, maxWidth: 360, padding: 20, background: "#FAF7F2", color: "#241430", border: "1.5px solid #24143022", borderRadius: 12 }}>
      <header style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, marginBottom: 14 }}>
        <h3 style={{ margin: 0, fontSize: 17, fontWeight: 600 }}>{title}</h3>
        <span style={{ fontSize: 12, color: "#241430", opacity: 0.6, whiteSpace: "nowrap" }}>Showing last {entriesShown} updates</span>
      </header>
      <ol style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: listGap }}>
        {entries.map((entry, i) => (
          <li key={entry.date} style={{ position: "relative", paddingLeft: variant === "timeline" ? 18 : 14, borderLeft: "2px solid " + accent }}>
            {variant === "timeline" && (
              <span style={{ position: "absolute", left: -5, top: 3, width: 8, height: 8, borderRadius: "50%", background: accent, border: "2px solid #FAF7F2" }} />
            )}
            {i === 0 && showNew && (
              <span style={{ position: "absolute", right: 0, top: 0, background: accent, color: "#241430", fontSize: 10, fontWeight: 700, padding: "2px 7px", borderRadius: 999, textTransform: "uppercase", letterSpacing: ".04em" }}>New</span>
            )}
            <span style={{ display: "block", fontSize: 11, fontWeight: 600, letterSpacing: ".04em", textTransform: "uppercase", color: accent, marginBottom: 2 }}>{entry.date}</span>
            <p style={{ margin: 0, fontSize: variant === "compact" ? 12.5 : 13.5, color: "#241430cc" }}>{entry.text}</p>
          </li>
        ))}
      </ol>
    </section>
  );
}
